1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives the canonical region ('locality') for an owner. The region is resolved by the
7	 * postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only falls back
8	 * to the fixed city-to-region table when the postcode is absent or in no known range. This
9	 * returns the same region for known cities but disambiguates cities that share a name.
10	 * An owner with neither a known postcode range nor a known city derives 'UNKNOWN'.
11	 */
12	public final class Locality {
13	
14	    /** City -> canonical region. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
17	
18	    /** Region -> inclusive 4-digit postcode range {low, high}. */
19	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
20	            "NSW", new int[] {2000, 2099},
21	            "VIC", new int[] {3000, 3099},
22	            "QLD", new int[] {4000, 4099});
23	
24	    /** Region -> IANA timezone name. */
25	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
26	            "NSW", "Australia/Sydney",
27	            "VIC", "Australia/Melbourne",
28	            "QLD", "Australia/Brisbane");
29	
30	    public static final String UNKNOWN = "UNKNOWN";
31	
32	    private Locality() {
33	    }
34	
35	    /** The canonical region for {@code city}, or {@code UNKNOWN} when not in the table. */
36	    public static String of(String city) {
37	        return CITY_REGION.getOrDefault(city, UNKNOWN);
38	    }
39	
40	    /**
41	     * The canonical region, preferring the {@code postcode} range. When the postcode is
42	     * absent or in no known range, falls back to the {@code city} table (see {@link #of(String)}).
43	     */
44	    public static String of(String city, String postcode) {
45	        String byPostcode = fromPostcode(postcode);
46	        return byPostcode != null ? byPostcode : of(city);
47	    }
48	
49	    /** The IANA timezone name for {@code region}, or {@code null} when the region has none. */
50	    public static String timezone(String region) {
51	        return REGION_TIMEZONE.get(region);
52	    }
53	
54	    /** Region whose inclusive range contains {@code postcode}, or {@code null} if none. */
55	    private static String fromPostcode(String postcode) {
56	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
57	            return null;
58	        }
59	        int value = Integer.parseInt(postcode);
60	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
61	            int[] range = entry.getValue();
62	            if (value >= range[0] && value <= range[1]) {
63	                return entry.getKey();
64	            }
65	        }
66	        return null;
67	    }
68	}
