1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Objects;
4	import java.util.Set;
5	import java.util.stream.Collectors;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.util.Locality;
11	import org.springframework.samples.petclinic.util.MemberId;
12	
13	/**
14	 * Assigns the owner's {@code memberId}, formatted {@code '<REGION><FY><HASH8><CHK>'} where REGION is
15	 * the region derived from the owner's postcode (falling back to the city table, see {@link Locality}),
16	 * FY is the two-digit fiscal year of the registration date, HASH8 is the first eight upper-case hex
17	 * characters of SHA-256 over the {@code normalizedTelephone + lastName} and CHK is a single Luhn check
18	 * digit over the digits of {@code <REGION><FY><HASH8>} (e.g. 'NSW271A2B3C4D5'). Runs after the owner is
19	 * built (so the telephone is already normalized to E.164 and the registration date populated) and before
20	 * it is saved, mutating the id in place via {@code @Val} for the save/respond steps to persist and return.
21	 *
22	 * <p>When the computed id collides with an existing owner's {@code memberId}, {@code '-<n>'} is appended
23	 * with the smallest {@code n} of 2 or more that makes it unique, and the de-duplicated id is assigned
24	 * (e.g. a second 'NSW271A2B3C4D5' becomes 'NSW271A2B3C4D5-2', a third 'NSW271A2B3C4D5-3').
25	 */
26	public class AssignMemberId {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String region = Locality.of(owner.getCity(), owner.getPostcode());
30	        String base = MemberId.of(region, owner.getRegistrationDate(), owner.getTelephone(),
31	                owner.getLastName());
32	        Set<String> existing = ownerRepository.findAll().stream()
33	                .map(Owner::getMemberId)
34	                .filter(Objects::nonNull)
35	                .collect(Collectors.toSet());
36	        String memberId = base;
37	        for (int n = 2; existing.contains(memberId); n++) {
38	            memberId = base + "-" + n;
39	        }
40	        owner.setMemberId(memberId);
41	    }
42	}
