3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Runs after {@link BuildOwner}. Assigns the deterministic {@code householdId} derived from the owner's
8	 * last name and postcode ({@link OwnerIdentity#householdId}). Because the id is a pure function of
9	 * (lastName, postcode), every owner with the same last name and postcode receives the same value with no
10	 * back-fill: they simply share the household automatically. This runs for every owner — {@code
11	 * sharesHousehold} no longer decides whether the link is created, it only bypasses the duplicate block
12	 * upstream in {@link EnsureUniqueOwnerIdentity}.
13	 */
14	public class AssignOwnerHousehold {
15	
16	    public void service(@Val Owner owner) {
17	        owner.setHouseholdId(OwnerIdentity.householdId(owner.getLastName(), owner.getPostcode()));
18	    }
19	}
