1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Immutable structured audit event emitted on a successful owner create. Serialized to JSON and
5	 * published on the {@code AUDIT} logger alongside the human-readable audit line.
6	 *
7	 * <p>{@code identifier} carries the owner's <em>primary identifier</em>, the unified {@code memberId}.
8	 * The JSON field is named {@code memberId} to match the published contract.
9	 */
10	public record OwnerCreatedEvent(long seq, Integer ownerId, String identifier, int membershipLevel) {
11	
12	    private static final String EVENT = "OWNER_CREATED";
13	
14	    /** Renders the event as the canonical JSON object
15	     *  {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}. */
16	    public String toJson() {
17	        return "{"
18	            + "\"seq\":" + seq
19	            + ",\"ownerId\":" + ownerId
20	            + ",\"memberId\":" + quote(identifier)
21	            + ",\"membershipLevel\":" + membershipLevel
22	            + ",\"event\":\"" + EVENT + "\""
23	            + "}";
24	    }
25	
26	    private static String quote(String value) {
27	        if (value == null) {
28	            return "null";
29	        }
30	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
31	        for (int i = 0; i < value.length(); i++) {
32	            char c = value.charAt(i);
33	            switch (c) {
34	                case '"' -> sb.append("\\\"");
35	                case '\\' -> sb.append("\\\\");
36	                case '\n' -> sb.append("\\n");
37	                case '\r' -> sb.append("\\r");
38	                case '\t' -> sb.append("\\t");
39	                default -> {
40	                    if (c < 0x20) {
41	                        sb.append(String.format("\\u%04x", (int) c));
42	                    } else {
43	                        sb.append(c);
44	                    }
45	                }
46	            }
47	        }
48	        return sb.append('"').toString();
49	    }
50	}
