1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.concurrent.atomic.AtomicLong;
5	
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.util.MembershipLevel;
12	
13	/**
14	 * Emits an audit line on successful create via the dedicated {@code AUDIT} logger, carrying the
15	 * newly-assigned owner id, the {@code memberId}, the {@code registrationDate} and the derived
16	 * {@code membershipLevel}. Runs after {@code SaveOwner} so the owner id is populated.
17	 *
18	 * <p>Alongside the human-readable line it emits an immutable structured {@link OwnerCreatedEvent} as
19	 * JSON on the same logger, carrying a {@code seq} that increases monotonically across creates and the
20	 * owner's primary identifier (the {@code memberId}).
21	 */
22	public class AuditOwnerCreated {
23	
24	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
25	
26	    /** Monotonically increasing sequence across all owner-created events for this application. */
27	    private static final AtomicLong SEQ = new AtomicLong();
28	
29	    public void service(@Val Owner owner) {
30	        int membershipLevel = MembershipLevel.level(MembershipLevel.points(owner.getEmail(),
31	            owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate(),
32	            LocalDate.now()));
33	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
34	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
35	
36	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
37	            owner.getMemberId(), membershipLevel);
38	        AUDIT.info(event.toJson());
39	    }
40	}
