package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Runs after {@link BuildOwner}. Assigns the deterministic {@code householdId} derived from the owner's
 * last name and postcode ({@link OwnerIdentity#householdId}). Because the id is a pure function of
 * (lastName, postcode), every owner with the same last name and postcode receives the same value with no
 * back-fill: they simply share the household automatically. This runs for every owner — {@code
 * sharesHousehold} no longer decides whether the link is created, it only bypasses the duplicate block
 * upstream in {@link EnsureUniqueOwnerIdentity}.
 */
public class AssignOwnerHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(OwnerIdentity.householdId(owner.getLastName(), owner.getPostcode()));
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "selfLink",
        expression = "java(\"/api/owners/\" + owner.getId())")
    @Mapping(target = "displayName",
        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "salutation",
        expression = "java(owner.getTitle() == null || owner.getTitle().isBlank() "
            + "? owner.getLastName() : owner.getTitle() + \" \" + owner.getLastName())")
    @Mapping(target = "initials",
        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
    @Mapping(target = "fiscalYear",
        expression = "java(org.springframework.samples.petclinic.util.FiscalYear.label("
            + "owner.getRegistrationDate()))")
    @Mapping(target = "membershipPoints",
        expression = "java(org.springframework.samples.petclinic.util.MembershipLevel.points("
            + "owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), "
            + "owner.getRegistrationDate(), java.time.LocalDate.now()))")
    @Mapping(target = "membershipLevel",
        expression = "java(owner.getMembershipLevel() != null ? owner.getMembershipLevel() "
            + ": org.springframework.samples.petclinic.util.MembershipLevel.level("
            + "org.springframework.samples.petclinic.util.MembershipLevel.points("
            + "owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), "
            + "owner.getRegistrationDate(), java.time.LocalDate.now())))")
    @Mapping(target = "telephoneDisplay",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneE164"
            + ".toDisplay(owner.getTelephone()))")
    @Mapping(target = "identityKey",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity"
            + ".key(owner.getTelephone(), owner.getEmail(), owner.getLastName()))")
    @Mapping(target = "locality",
        expression = "java(org.springframework.samples.petclinic.util.Locality.of("
            + "owner.getCity(), owner.getPostcode()))")
    @Mapping(target = "timezone",
        expression = "java(org.springframework.samples.petclinic.util.Locality.timezone("
            + "org.springframework.samples.petclinic.util.Locality.of(owner.getCity(), owner.getPostcode())))")
    @Mapping(target = "ownerSegment",
        expression = "java(org.springframework.samples.petclinic.util.OwnerSegment.of("
            + "owner.getMembershipLevel() != null ? owner.getMembershipLevel() "
            + ": org.springframework.samples.petclinic.util.MembershipLevel.level("
            + "org.springframework.samples.petclinic.util.MembershipLevel.points("
            + "owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), "
            + "owner.getRegistrationDate(), java.time.LocalDate.now())), "
            + "org.springframework.samples.petclinic.util.Locality.of(owner.getCity(), owner.getPostcode())))")
    @Mapping(target = "contactPreference",
        expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() "
            + "? org.springframework.samples.petclinic.rest.dto.OwnerDto.ContactPreferenceEnum.EMAIL "
            + ": org.springframework.samples.petclinic.rest.dto.OwnerDto.ContactPreferenceEnum.PHONE)")
    @Mapping(target = "ageBand",
        expression = "java(owner.getBirthDate() == null ? null "
            + ": org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.fromValue("
            + "org.springframework.samples.petclinic.util.AgeBand.of("
            + "owner.getBirthDate(), owner.getRegistrationDate())))")
    @Mapping(target = "riskFlag",
        expression = "java(org.springframework.samples.petclinic.util.RiskFlag.of(owner))")
    OwnerDto toOwnerDto(Owner owner);

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

